using System;using System.Linq;using System.Collections.Generic;using System.Diagnostics;using System.ComponentModel;using System.Threading;using System.Threading.Tasks;using System.Text.RegularExpressions;
public class ProcessUsageEntry {public string Name;public int Count;public double? Cpu,Gpu;}
public class ProcessUsageSnapshot {public DateTime Utc;public string CpuState="等待两次CPU采样",GpuState="等待GPU引擎采样";public ProcessUsageEntry[] Entries=new ProcessUsageEntry[0];}
public class ProcessCpuStamp {public int Id;public string Name;public long Start,Cpu;}
public class ProcessGpuReading {public int Id;public string Engine;public double Value;}
public static class ProcessUsageLogic {
 public static double? CpuPercent(ProcessCpuStamp previous,ProcessCpuStamp current,double seconds,int cores){if(previous==null||previous.Id!=current.Id||previous.Start!=current.Start||Double.IsNaN(seconds)||Double.IsInfinity(seconds)||seconds<=0||seconds>15||cores<1||current.Cpu<previous.Cpu)return null;return Math.Max(0,Math.Min(100,(current.Cpu-previous.Cpu)/(double)TimeSpan.TicksPerSecond/seconds/cores*100));}
 public static ProcessUsageEntry[] Group(IEnumerable<ProcessCpuStamp> current,IDictionary<int,ProcessCpuStamp> previous,double seconds,int cores,IEnumerable<ProcessGpuReading> engines){var gpu=(engines??new ProcessGpuReading[0]).Where(x=>!Double.IsNaN(x.Value)&&!Double.IsInfinity(x.Value)&&x.Value>=0).ToArray();return current.GroupBy(p=>p.Name,StringComparer.OrdinalIgnoreCase).Select(group=>{var cpu=group.Select(p=>CpuPercent(previous.ContainsKey(p.Id)?previous[p.Id]:null,p,seconds,cores)).Where(v=>v.HasValue).ToArray();var ids=new HashSet<int>(group.Select(p=>p.Id));var loads=gpu.Where(x=>ids.Contains(x.Id)).GroupBy(x=>x.Engine).Select(x=>Math.Min(100,x.Sum(v=>v.Value))).ToArray();return new ProcessUsageEntry{Name=group.Key,Count=group.Count(),Cpu=cpu.Length==0?null:(double?)Math.Min(100,cpu.Sum(v=>v.Value)),Gpu=loads.Length==0?null:(double?)loads.Max()};}).ToArray();}
 public static string AppName(string name){switch((name??"").ToLowerInvariant()){case "chrome":return "Google Chrome";case "msedge":return "Microsoft Edge";case "code":return "Visual Studio Code";case "explorer":return "Windows资源管理器";case "dwm":return "桌面窗口管理器";default:return (name??"未知进程")+".exe";}}
 public static string Report(ProcessUsageSnapshot snapshot,string resource,int count,DateTime now){count=Math.Max(1,Math.Min(10,count));if(snapshot==null||snapshot.Utc==default(DateTime)||now<snapshot.Utc||now-snapshot.Utc>TimeSpan.FromSeconds(10))return "进程排行尚未就绪，约3秒后重试。";bool gpu=resource=="gpu";var entries=snapshot.Entries.Where(e=>(gpu?e.Gpu:e.Cpu).HasValue&&(gpu?e.Gpu:e.Cpu).Value>=.1).OrderByDescending(e=>(gpu?e.Gpu:e.Cpu).Value).ThenBy(e=>e.Name,StringComparer.OrdinalIgnoreCase).Take(count).ToArray();string heading=(gpu?"GPU":"CPU")+" 占用 Top "+count+"（"+snapshot.Utc.ToLocalTime().ToString("HH:mm:ss")+"）";if(entries.Length==0)return heading+"\n"+(gpu?snapshot.GpuState:snapshot.CpuState)+"；暂无可报告的活跃进程。";return heading+"\n"+String.Join("\n",entries.Select((e,i)=>(i+1)+". "+AppName(e.Name)+" · "+(gpu?e.Gpu:e.Cpu).Value.ToString("F1")+"%"+(e.Count>1?"（"+e.Count+"个进程）":"")));}
 public static string AlertText(string text,string key,ProcessUsageSnapshot snapshot,int count,DateTime now){string resource=key.Split('@',':')[0];return resource=="cpu"||resource=="gpu"?text+"\n"+Report(snapshot,resource,count,now):text;}
}
public sealed class ProcessUsageSampler:IDisposable {
 volatile bool disposed;int busy;double sampled=-10;readonly Stopwatch clock=Stopwatch.StartNew();double previousTime;Dictionary<int,ProcessCpuStamp> previous=new Dictionary<int,ProcessCpuStamp>();Dictionary<string,CounterSample> gpuPrevious=new Dictionary<string,CounterSample>();volatile ProcessUsageSnapshot latest;
 public ProcessUsageSnapshot Current{get{return latest;}}
 public ProcessUsageSnapshot Poll(bool enabled){if(!enabled){latest=null;return null;}double now=clock.Elapsed.TotalSeconds;if(!disposed&&now-sampled>=3&&Interlocked.CompareExchange(ref busy,1,0)==0){sampled=now;Task.Run(()=>{try{Capture();}catch(Exception e){if(!Expected(e))throw;if(!disposed)latest=new ProcessUsageSnapshot{Utc=DateTime.UtcNow,CpuState="Windows进程采样不可用",GpuState="进程采样不可用，等待重试"};}finally{Interlocked.Exchange(ref busy,0);}});}var value=latest;return value!=null&&DateTime.UtcNow>=value.Utc&&DateTime.UtcNow-value.Utc<=TimeSpan.FromSeconds(10)?value:null;}
 static bool Expected(Exception e){return e is InvalidOperationException||e is Win32Exception||e is UnauthorizedAccessException||e is System.Security.SecurityException||e is NotSupportedException;}
 void Capture(){if(disposed)return;var current=new List<ProcessCpuStamp>();int denied=0;foreach(var process in Process.GetProcesses())using(process){if(disposed)return;try{if(process.Id<=0)continue;var stamp=new ProcessCpuStamp{Id=process.Id,Name=process.ProcessName};try{stamp.Start=process.StartTime.ToUniversalTime().Ticks;stamp.Cpu=process.TotalProcessorTime.Ticks;}catch(Exception e){if(!Expected(e))throw;denied++;stamp.Start=0;stamp.Cpu=0;}current.Add(stamp);}catch(Exception e){if(!Expected(e))throw;denied++;}}
  string gpuState;var engines=ReadGpu(out gpuState);double now=clock.Elapsed.TotalSeconds;var entries=ProcessUsageLogic.Group(current.Where(p=>p.Start>0),previous,now-previousTime,Environment.ProcessorCount,engines);bool warm=previous.Count>0;previous=current.Where(p=>p.Start>0).ToDictionary(x=>x.Id);previousTime=now;var value=new ProcessUsageSnapshot{Utc=DateTime.UtcNow,Entries=entries,CpuState=warm?"按整机逻辑核心归一化；部分受保护进程可能不可读":"等待第二次CPU采样",GpuState=gpuState};if(denied>0)value.CpuState+="（"+denied+"项不可读）";if(!disposed)latest=value;
 }
 static readonly Regex EnginePattern=new Regex(@"^pid_(\d+)_(luid_.+?_phys_\d+_eng_\d+)_engtype_",RegexOptions.CultureInvariant);
 ProcessGpuReading[] ReadGpu(out string state){var values=new List<ProcessGpuReading>();var next=new Dictionary<string,CounterSample>();bool warm=false;try{var data=new PerformanceCounterCategory("GPU Engine").ReadCategory()["Utilization Percentage"];if(data==null){state="Windows GPU引擎计数器不可用";return values.ToArray();}foreach(string key in data.Keys){var match=EnginePattern.Match(key);int id;if(!match.Success||!Int32.TryParse(match.Groups[1].Value,out id))continue;var sample=data[key].Sample;next[key]=sample;CounterSample old;if(!gpuPrevious.TryGetValue(key,out old))continue;warm=true;double value=CounterSample.Calculate(old,sample);if(!Double.IsNaN(value)&&!Double.IsInfinity(value)&&value>=0)values.Add(new ProcessGpuReading{Id=id,Engine=match.Groups[2].Value,Value=value});}gpuPrevious=next;state=warm?"Windows GPU Engine · 同一软件最繁忙引擎；不等同驱动整卡读数":"GPU引擎预热，等待下一次采样";}catch(Exception e){if(!Expected(e))throw;gpuPrevious.Clear();state="Windows GPU引擎不可用或权限不足";}return values.ToArray();}
 public void Dispose(){disposed=true;latest=null;}
}
